arguments.command:
tmp=$(mktemp); for b in rachel monica phoebe joey chandler ross; do git log --reverse --format='%H%x09%ci%x09%B%x1f' origin/friend/$b | awk -v RS='\x1f' -v branch="$b" '
BEGIN{FS="\t"}
{
  sha=$1; ts=$2; msg=$3;
  if (msg ~ /Friend-Message: 1/ && msg ~ /Episode: S07\/E08/) {
    # extract commit timestamp ISO from ts
    print ts "\t" sha "\t" branch "\t" msg
  }
}' >> "$tmp";
done
wc -l "$tmp"; echo "--- sorted preview ---"; sort -k1,1 -k2,2 "$tmp" | cut -f1-3
